const expectedBaseCount = 191;
const expectedTotalCount = 192;

const expectedCategoryCounts = {
  "SUPER TOP": 3,
  "TOP": 6,
  "SEMITOP": 10,
  "SOTTO AI SEMITOP": 7,
  "FASCIA ALTA": 9,
  "JOLLY 1ª FASCIA": 5,
  "POSSIBILI SORPRESE": 5,
  "FASCIA MEDIA": 7,
  "INFORTUNATI": 4,
  "SCOMMESSE": 11,
  "SOPRA AI LOW COST": 9,
  "JOLLY 2ª FASCIA": 15,
  "LOW COST 1ª FASCIA": 12,
  "LOW COST 2ª FASCIA": 16,
  "LEGHE NUMEROSE": 10,
  "JOLLY 3ª FASCIA": 14,
  "JOLLY 4ª FASCIA": 25,
  "A RISCHIO": 14,
  "DA EVITARE": 5,
  "MERCATO": 4,
};

const _base = CENTROCAMPISTI.filter((p) => p.fascia !== "EXTRA AGGIORNAMENTI LIVE");

if (_base.length !== expectedBaseCount) {
  console.error(`Base SOS centrocampisti incompleta: ${_base.length}/${expectedBaseCount}`);
}

if (CENTROCAMPISTI.length !== expectedTotalCount) {
  console.error(`Dataset Centrocampisti V4 incompleto: ${CENTROCAMPISTI.length}/${expectedTotalCount}`);
} else {
  console.log(`Total centrocampisti: ${CENTROCAMPISTI.length}`);
}

const _counts = {};
_base.forEach((p) => {
  _counts[p.fascia] = (_counts[p.fascia] || 0) + 1;
});
Object.entries(expectedCategoryCounts).forEach(([fascia, atteso]) => {
  const attuale = _counts[fascia] || 0;
  if (attuale !== atteso) {
    console.error(`Categoria centrocampisti "${fascia}": ${attuale}/${atteso}`);
  }
});

const _ids = CENTROCAMPISTI.map((p) => p.id);
if (new Set(_ids).size !== _ids.length) {
  console.error("ID duplicati nel dataset Centrocampisti V4");
}

export function getCentrocampistaByNome(nome) {
  return CENTROCAMPISTI.find((c) => c.nome === nome);
}

export function getCentrocampistaById(id) {
  return CENTROCAMPISTI.find((c) => c.id === id);
}

export function getCentrocampistiByFascia(fascia) {
  return CENTROCAMPISTI.filter((c) => c.fascia === fascia);
}

export function getCentrocampistiByTag(tag) {
  return CENTROCAMPISTI.filter((c) => c.tags && c.tags.includes(tag));
}
